toolArgs.file_text:
@page "/book-appointment"
@rendermode InteractiveServer
@using sv_f781032c5be14e2aa165f134865763a7.Models
@using sv_f781032c5be14e2aa165f134865763a7.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        <h4>Appointment Confirmed!</h4>
        <p><strong>Patient:</strong> @Model.Name</p>
        <p><strong>Doctor:</strong> @Model.Doctor</p>
        <p><strong>Date:</strong> @Model.Date?.ToString("MMMM d, yyyy")</p>
        <p><strong>Time:</strong> @Model.TimeSlot</p>
        <button class="btn btn-primary" @onclick="Reset">Book Another</button>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        @* ───── STEP 1 ───── *@
        <fieldset>
            <legend>Patient Information</legend>

            <div class="mb-3">
                <label class="form-label" for="name">Patient Name</label>
                <InputText id="name" class="form-control" @bind-Value="Model.Name" />
                <ValidationMessage For="() => Model.Name" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <InputText id="email" class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="insurance">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>
        </fieldset>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
                @(isProcessing ? "Checking..." : "Next: Schedule Appointment")
            </button>
        }

        @* ───── STEP 2 ───── *@
        @if (showStep2)
        {
            <fieldset class="mt-4">
                <legend>Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label" for="doctor">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select a Doctor --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="date">Appointment Date</label>
                    <InputDate id="date" class="form-control" @bind-Value="Model.Date"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => Model.Date" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeslot">Time Slot</label>
                    <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select a Time --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" @bind-Value="Model.Reason" rows="3" />
                    <ValidationMessage For="() => Model.Reason" />
                    @if (Model.Reason is not null)
                    {
                        <small class="text-muted">@Model.Reason.Length / 500</small>
                    }
                </div>
            </fieldset>

            <div class="mt-3 d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">Back</button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isProcessing">
                    @(isProcessing ? "Checking..." : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isProcessing)">
                    Confirm Appointment
                </button>
            </div>
        }
    </EditForm>
}

@code {
    private AppointmentModel Model = new();
    private EditContext editContext = null!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool submitted;
    private bool isProcessing;
    private bool availabilityChecked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task ProceedToStep2()
    {
        // Validate only step-1 fields
        var step1Valid = IsStep1Valid();
        if (!step1Valid)
        {
            editContext.NotifyValidationStateChanged();
            return;
        }

        isProcessing = true;
        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
        isProcessing = false;
    }

    private bool IsStep1Valid()
    {
        var isValid = true;

        if (string.IsNullOrWhiteSpace(Model.Name))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            isValid = false;

        // Trigger field validation so messages appear
        editContext.Validate();

        return isValid;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        Model.TimeSlot = null;
        availableSlots = [];

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.Date.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(Model.Doctor, Model.Date.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;

        if (string.IsNullOrEmpty(Model.Doctor) || !Model.Date.HasValue || string.IsNullOrEmpty(Model.TimeSlot))
        {
            editContext.Validate();
            return;
        }

        // Future-date validation
        if (Model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                ["Date"] = ["Appointment date must be in the future."]
            });
            return;
        }

        isProcessing = true;

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email!,
            Model.InsuranceProvider!,
            Model.Doctor,
            Model.TimeSlot);

        isProcessing = false;

        if (errors.Count > 0)
        {
            customValidator?.DisplayErrors(errors);
            return;
        }

        availabilityChecked = true;
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        // Future-date validation at submit time too
        if (Model.Date!.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                ["Date"] = ["Appointment date must be in the future."]
            });
            return;
        }

        submitted = true;
        await Task.CompletedTask;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private void Reset()
    {
        Model = new();
        editContext = new EditContext(Model);
        showStep2 = false;
        submitted = false;
        availabilityChecked = false;
        availableSlots = [];
    }
}

